#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

#define int long long
const int MOD_A = 998244353, MOD_B = 1000000007;
const int powers[] = {1, 10, 100, 1000, 10000, 100000, 1000000};

int sum_arr[7], result, count_seq1, max_num, count_seq2;
vector<int> sequences[7];

void build_sequences(int depth, int val) {
    if (depth == 7) return;
    sequences[depth].push_back((count_seq1 - val + MOD_A) % MOD_A);
    sum_arr[depth] += (count_seq1 - val + MOD_A) % MOD_A;
    count_seq1++;
    for (int digit = 0; digit <= 9; ++digit) {
        build_sequences(depth + 1, val * 10 + digit);
    }
}

bool check_range(int x) {
    return x * powers[6] + 999999 <= max_num && x * powers[6] * 10 > max_num;
}

void traverse(int level, int current_value) {
    if (current_value > max_num) return;
    if (check_range(current_value)) {
        for (int i = 0; i <= 6; ++i) {
            int p = ((count_seq2 + 1 - (current_value * powers[i])) % MOD_A + MOD_A) % MOD_A;
            int pos = (int)(lower_bound(sequences[i].begin(), sequences[i].end(), MOD_A - p) - sequences[i].begin());
            result = (result + (sum_arr[i] + p * sequences[i].size() - MOD_A * (sequences[i].size() - pos))) % MOD_B;
        }
        count_seq2 += count_seq1;
        return;
    }
    count_seq2++;
    result = (result + ((count_seq2 - current_value) % MOD_A + MOD_A) % MOD_A) % MOD_B;
    for (int digit = (level == 0 ? 1 : 0); digit <= 9; ++digit) {
        traverse(level + 1, current_value * 10 + digit);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> max_num;
    build_sequences(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(sequences[i].begin(), sequences[i].end());
    }
    count_seq2 = -1;
    traverse(0, 0);
    cout << result << '\n';
    return 0;
}
